const f = msg.payload;
const out_readings = null;

// 1) scalar readings -> measurement 'telemetry'
const fields = {};
for (const [name, r] of Object.entries(f.readings || {})) {
  fields[name] = r.v;
}
fields.seq = f.seq;
const readingsMsg = {
  payload: [fields, { device_id: f.device_id }],
  measurement: 'telemetry'
};

// 2) discrete events -> measurement 'events' (one point per event)
// confidence as field; label + channel as tags; count/level as fields if present.
const eventMsgs = [];
const shots = flow.get('shots') || [];
for (const e of (f.events || [])) {
  if (e.ch === 'vision' && e.label === 'person' && e.meta && e.meta.snapshot) {
    shots.push({ file: e.meta.snapshot.split('/').pop(), count: e.meta.count||0,
                 label: e.label, ts: new Date(f.ts*1000).toLocaleTimeString() });
    if (shots.length > 200) shots.shift();
    flow.set('shots', shots);
  }
  const efields = { confidence: e.conf };
  if (e.meta && typeof e.meta.count === 'number') efields.count = e.meta.count;
  if (e.meta && typeof e.meta.level_dbfs === 'number') efields.level_dbfs = e.meta.level_dbfs;
  eventMsgs.push({
    payload: [efields, { device_id: f.device_id, channel: e.ch, label: e.label }],
    measurement: 'events'
  });
}

return [readingsMsg, eventMsgs];

// Reads recent vision events from flow context (populated by the split fn)
const shots = flow.get('shots') || [];
const cards = shots.slice(-24).reverse().map(s =>
  `<div class=card><img src='/snap/${s.file}'/><div class=meta>${s.label} \u00d7${s.count} \u2014 ${s.ts}</div></div>`
).join('');
msg.payload = `<!doctype html><html><head><meta charset=utf-8>`+
  `<meta http-equiv=refresh content=5><title>Sentinel \u2014 camera</title>`+
  `<style>body{background:#0d1117;color:#c9d1d9;font-family:system-ui;margin:0;padding:20px}`+
  `h1{color:#3fb950;font-size:18px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}`+
  `.card{background:#161b22;border:1px solid #30363d;border-radius:8px;overflow:hidden}`+
  `.card img{width:100%;display:block}.meta{padding:8px;font-size:13px;color:#8b949e}</style></head>`+
  `<body><h1>\ud83d\udee1\ufe0f sentinel-01 \u2014 camera snapshots</h1><div class=grid>${cards}</div></body></html>`;
msg.headers = { 'Content-Type': 'text/html' };
return msg;

const fs = global.get('fs');
const dir = env.get('SNAPSHOT_DIR') || 'C:/sentinel/snaps';
const file = (msg.req.params.file || '').replace(/[^0-9A-Za-z_.-]/g, '');
if (!fs) {
    msg.statusCode = 500;
    msg.headers = { 'Content-Type': 'text/plain' };
    msg.payload = "fs not available: add functionGlobalContext: { fs: require('fs') } to settings.js";
    return msg;
}
if (!file) { msg.statusCode = 400; msg.payload = 'missing file'; return msg; }
const full = dir + '/' + file;
try {
    const buf = fs.readFileSync(full);
    msg.statusCode = 200;
    msg.headers = { 'Content-Type': 'image/jpeg' };
    msg.payload = buf;
} catch (e) {
    msg.statusCode = 404;
    msg.headers = { 'Content-Type': 'text/plain' };
    msg.payload = 'not found';
}
return msg;
